import{_ as a,c as n,d as e,Z as l}from"./chunks/framework.B0uuYL3Y.js";const o="/microarch/meltdown-dataflow.png",h=JSON.parse('{"title":"Meltdown 中的越权加载如何影响后续指令","description":"从一条 x86 加载出发，算出页错误，再把内部数据传递和异常交付放在同一条时间线上。","frontmatter":{"title":"Meltdown 中的越权加载如何影响后续指令","description":"从一条 x86 加载出发，算出页错误，再把内部数据传递和异常交付放在同一条时间线上。","date":"2026-11-25","tags":["微架构安全","Meltdown","页表","瞬态执行"],"book":"microarch-00-intro"},"headers":[],"relativePath":"posts/microarch-04e-meltdown.md","filePath":"posts/microarch-04e-meltdown.md"}'),p={name:"posts/microarch-04e-meltdown.md"};function r(t,s,c,i,d,y){return n(),e("div",null,s[0]||(s[0]=[l(`<p>用户态执行一条读取指令，目标页存在，却只允许内核访问。按 x86 的架构规则，这条指令会触发页错误，加载结果不会成为程序可见的寄存器值。经典 Meltdown 讨论的是发生在部分处理器内部的另一件事：这条会报错的加载，在异常交付之前仍可能短暂地把值交给后面的指令。</p><p>这条路径从加载的权限异常开始，即使前面没有条件分支，问题也成立。要讲清它，先把同一条加载的<strong>地址翻译、权限判断和异常交付</strong>分别算出来。</p><nav class="table-of-contents"><ul><li><a href="#一条加载要同时满足地址和权限">一条加载要同时满足地址和权限</a></li><li><a href="#为什么报错和短暂传递数据可以同时成立">为什么报错和短暂传递数据可以同时成立</a></li><li><a href="#同一段窗口里-哪条指令能说明数据相依">同一段窗口里，哪条指令能说明数据相依</a></li><li><a href="#用同一组数值核对三种结果">用同一组数值核对三种结果</a></li><li><a href="#页表隔离改的是哪一步">页表隔离改的是哪一步</a></li><li><a href="#参考文献">参考文献</a></li></ul></nav><h2 id="一条加载要同时满足地址和权限" tabindex="-1">一条加载要同时满足地址和权限 <a class="header-anchor" href="#一条加载要同时满足地址和权限" aria-label="Permalink to &quot;一条加载要同时满足地址和权限&quot;">​</a></h2><p>下列 x86-64 指令为本节分析编写。第一条从 <code>rdi</code> 指向的位置读取四字节，第二条需要这个值，第三条访问另一处地址。</p><div class="language-asm line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">asm</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#859900;">mov</span><span style="color:#B58900;"> eax</span><span style="color:#839496;">, </span><span style="color:#93A1A1;font-weight:bold;">DWORD</span><span style="color:#839496;"> PTR [</span><span style="color:#B58900;">rdi</span><span style="color:#839496;">]</span></span>
<span class="line"><span style="color:#859900;">add</span><span style="color:#B58900;"> eax</span><span style="color:#839496;">, </span><span style="color:#D33682;">1</span></span>
<span class="line"><span style="color:#859900;">mov</span><span style="color:#B58900;"> ecx</span><span style="color:#839496;">, </span><span style="color:#93A1A1;font-weight:bold;">DWORD</span><span style="color:#839496;"> PTR [</span><span style="color:#B58900;">rsi</span><span style="color:#839496;">]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>假定当前特权级 <code>CPL = 3</code>，<code>rdi</code> 中是符合 x86-64 地址格式的线性地址，目标的 4 KiB 映射存在，并且除了页面的用户／监督者权限之外没有别的拒绝条件。题设给定目标页物理基址为 <code>0x123000</code>，<code>rdi</code> 的低 12 位为 <code>0x020</code>。页号参与翻译，页内偏移保留，因此翻译给出的目标是 <code>0x123020</code>。访问四个字节没有跨页。若还不熟悉页内偏移，可先复算<a href="./microarch-02a-translation.html">地址翻译一节</a>中的例题。该篇用的是 RISC-V，本节的 U/S 和错误码按 x86 解释。</p><p>还要检查分页结构的访问权限。对本例的普通 x86 分页访问，有效的用户可访问性取决于这次翻译路径上的 U/S 权限。任一级把它限制为 supervisor-only，用户态读取就会因为保护检查失败触发页错误。如果只考虑页错误码的低三位，它们是 <code>101</code>。第 0 位为 1，表示保护违规，第 1 位为 0，表示读，第 2 位为 1，表示发自用户态。若将同一映射改成不存在，第 0 位改为 0。两种失败都可以叫页错误，原因不同。</p><h2 id="为什么报错和短暂传递数据可以同时成立" tabindex="-1">为什么报错和短暂传递数据可以同时成立 <a class="header-anchor" href="#为什么报错和短暂传递数据可以同时成立" aria-label="Permalink to &quot;为什么报错和短暂传递数据可以同时成立&quot;">​</a></h2><p>先看允许读取的情形。设进入这段指令前 <code>eax = 7</code>、<code>ecx = 8</code>。题设中 <code>[rdi]</code> 的四个字节按 x86 的字节序表示整数 41，<code>[rsi]</code> 是另一处有效地址，值为 73。第一条指令产生 41，<code>add</code> 得到 42，第三条独立读取 73。若三条指令正常提交，<code>eax = 42</code>、<code>ecx = 73</code>。</p><p>现在只改成 <code>[rdi]</code> 所在页为 supervisor-only。程序语义要求在第一条加载报告错误。乱序执行还要维护精确异常：故障指令及之后的指令不能提交，较早的指令仍按顺序完成。记录故障和把控制交给异常处理程序之间，可以经历一段时间。用一张表把内部事件和程序最终看到的结果对上：</p><table tabindex="0"><thead><tr><th>阶段</th><th>加载和后继指令的内部过程</th><th>程序可见的结果</th></tr></thead><tbody><tr><td>1. 地址翻译与访问检查</td><td>能给出本例的物理位置，用户态访问被判为权限违规</td><td>尚无加载结果提交</td></tr><tr><td>2. 故障等待交付</td><td>部分受影响的实现可能把真实加载值短暂送给依赖指令。若 <code>add</code> 得到 41，可以暂时算出 42</td><td>这些值仍是内部结果</td></tr><tr><td>3. 故障指令到达异常处理边界</td><td>处理器交付页错误，停止接纳故障指令及之后的结果</td><td>被中断的指令流仍保留先前提交的值，即 <code>eax = 7</code>、<code>ecx = 8</code></td></tr></tbody></table><figure class="lesson-figure"><a href="/microarch/meltdown-dataflow.png" aria-label="查看完整的数据与异常示意图"><img src="`+o+`" width="820" height="510" loading="lazy" alt="从故障加载分出两条路径。异常路径由权限检查走到记录页错误，再交付异常。数据路径在受影响的模型中从加载值 41 走到加法的内部结果 42，异常交付时该结果不提交，保留旧的 EAX 和 ECX。"></a><figcaption>顺着上排看页错误何时交付，再看下排的内部值 <code>41 → 42</code>。两排分别追踪异常和数据，方框间距只表示例题中的先后关系。图按本节题设绘制。</figcaption></figure><p>表中第一行列的是需要确定的事实，不能从该表推出某款处理器的权限检查电路与缓存读取谁先结束。公开资料能确认的是，特定实现即便最终交付故障，也可能曾把数据送给更年轻的操作。即便异常处理稍晚，只要实现把权限拒绝传播到数据转发逻辑，后续指令就拿不到真实值。精确异常规定程序最终看到什么，漏洞针对的是流水线内部在此之前传递过什么。</p><h2 id="同一段窗口里-哪条指令能说明数据相依" tabindex="-1">同一段窗口里，哪条指令能说明数据相依 <a class="header-anchor" href="#同一段窗口里-哪条指令能说明数据相依" aria-label="Permalink to &quot;同一段窗口里，哪条指令能说明数据相依&quot;">​</a></h2><p>对照第二和第三条指令。<code>add eax, 1</code> 的两个输入之一来自故障加载写入的内部寄存器版本。若在模型中将源值由 41 换成 80，它的计算结果也从 42 变为 81。这条依赖说明数据怎样向后传播。第三条指令的地址只看 <code>rsi</code>。若它在异常交付前已经发出请求，缓存可能发生变化，但该变化仍可以发生在替换源值以后，所以它不能说明源值通过缓存变得可区分。</p><p>这两种现象分开以后，就能准确理解经典 Meltdown 的安全链。某些受影响处理器上的故障加载能够将值交给后继操作。若该值后来影响了访存行为，缓存状态就可能反映这种区别，即使相关指令都没有退休。实际的安全结论还取决于这种差异能否到达给定的<a href="./microarch-04b-observation.html">观察者</a>。题设中的 <code>add</code> 用来追踪数据依赖，本身不访问缓存。</p><h2 id="用同一组数值核对三种结果" tabindex="-1">用同一组数值核对三种结果 <a class="header-anchor" href="#用同一组数值核对三种结果" aria-label="Permalink to &quot;用同一组数值核对三种结果&quot;">​</a></h2><p>下面把这三条指令缩成可运行的 Python 教学模型。程序只处理题设中的整数。参数 <code>page_user</code> 决定第一条是否有读权限，<code>forwards</code> 表示在这道题里是否假定受影响实现把整数交给了加法。模型另假定第三条在两种故障情形下都完成了内部加载，便于看出独立指令有没有提交。</p><div class="language-python line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#93A1A1;font-weight:bold;">def</span><span style="color:#268BD2;"> trace</span><span style="color:#839496;">(page_user, forwards):</span></span>
<span class="line"><span style="color:#839496;">    old_eax, old_ecx </span><span style="color:#859900;">=</span><span style="color:#D33682;"> 7</span><span style="color:#839496;">, </span><span style="color:#D33682;">8</span></span>
<span class="line"><span style="color:#839496;">    word_at_rdi, word_at_rsi </span><span style="color:#859900;">=</span><span style="color:#D33682;"> 41</span><span style="color:#839496;">, </span><span style="color:#D33682;">73</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">    # mov eax, [rdi] 和 add eax, 1</span></span>
<span class="line"><span style="color:#839496;">    load_value </span><span style="color:#859900;">=</span><span style="color:#839496;"> word_at_rdi </span><span style="color:#859900;">if</span><span style="color:#839496;"> page_user </span><span style="color:#859900;">or</span><span style="color:#839496;"> forwards </span><span style="color:#859900;">else</span><span style="color:#B58900;"> None</span></span>
<span class="line"><span style="color:#839496;">    add_result </span><span style="color:#859900;">=</span><span style="color:#B58900;"> None</span><span style="color:#859900;"> if</span><span style="color:#839496;"> load_value </span><span style="color:#859900;">is</span><span style="color:#B58900;"> None</span><span style="color:#859900;"> else</span><span style="color:#839496;"> (load_value </span><span style="color:#859900;">+</span><span style="color:#D33682;"> 1</span><span style="color:#839496;">) </span><span style="color:#859900;">&amp;</span><span style="color:#93A1A1;font-weight:bold;"> 0x</span><span style="color:#D33682;">ffffffff</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">    # mov ecx, [rsi] 的地址不依赖前两条指令</span></span>
<span class="line"><span style="color:#839496;">    independent_result </span><span style="color:#859900;">=</span><span style="color:#839496;"> word_at_rsi</span></span>
<span class="line"></span>
<span class="line"><span style="color:#859900;">    if</span><span style="color:#839496;"> page_user:</span></span>
<span class="line"><span style="color:#839496;">        committed </span><span style="color:#859900;">=</span><span style="color:#839496;"> (add_result, independent_result)</span></span>
<span class="line"><span style="color:#839496;">        page_fault </span><span style="color:#859900;">=</span><span style="color:#B58900;"> None</span></span>
<span class="line"><span style="color:#859900;">    else</span><span style="color:#839496;">:</span></span>
<span class="line"><span style="color:#839496;">        committed </span><span style="color:#859900;">=</span><span style="color:#839496;"> (old_eax, old_ecx)</span></span>
<span class="line"><span style="color:#839496;">        page_fault </span><span style="color:#859900;">=</span><span style="color:#93A1A1;font-weight:bold;"> 0b</span><span style="color:#D33682;">101</span></span>
<span class="line"><span style="color:#859900;">    return</span><span style="color:#839496;"> add_result, independent_result, committed, page_fault</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;"># 依次核对：加法的内部值、独立加载的内部值、已提交寄存器、页错误码。</span></span>
<span class="line"><span style="color:#859900;">assert</span><span style="color:#839496;"> trace(</span><span style="color:#B58900;">True</span><span style="color:#839496;">, </span><span style="color:#B58900;">False</span><span style="color:#839496;">) </span><span style="color:#859900;">==</span><span style="color:#839496;"> (</span><span style="color:#D33682;">42</span><span style="color:#839496;">, </span><span style="color:#D33682;">73</span><span style="color:#839496;">, (</span><span style="color:#D33682;">42</span><span style="color:#839496;">, </span><span style="color:#D33682;">73</span><span style="color:#839496;">), </span><span style="color:#B58900;">None</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#859900;">assert</span><span style="color:#839496;"> trace(</span><span style="color:#B58900;">False</span><span style="color:#839496;">, </span><span style="color:#B58900;">False</span><span style="color:#839496;">) </span><span style="color:#859900;">==</span><span style="color:#839496;"> (</span><span style="color:#B58900;">None</span><span style="color:#839496;">, </span><span style="color:#D33682;">73</span><span style="color:#839496;">, (</span><span style="color:#D33682;">7</span><span style="color:#839496;">, </span><span style="color:#D33682;">8</span><span style="color:#839496;">), </span><span style="color:#D33682;">5</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#859900;">assert</span><span style="color:#839496;"> trace(</span><span style="color:#B58900;">False</span><span style="color:#839496;">, </span><span style="color:#B58900;">True</span><span style="color:#839496;">) </span><span style="color:#859900;">==</span><span style="color:#839496;"> (</span><span style="color:#D33682;">42</span><span style="color:#839496;">, </span><span style="color:#D33682;">73</span><span style="color:#839496;">, (</span><span style="color:#D33682;">7</span><span style="color:#839496;">, </span><span style="color:#D33682;">8</span><span style="color:#839496;">), </span><span style="color:#D33682;">5</span><span style="color:#839496;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br></div></div><p>看最后两行。两种情形都交付同一个页错误，已提交寄存器也相同。唯一变动是加法能否得到数据。再看第一行。权限允许时，内部算到的 42 可以沿正常提交路径成为架构结果。模型由此把「有无内部结果」和「结果能否提交」分成两个判断。</p><h2 id="页表隔离改的是哪一步" tabindex="-1">页表隔离改的是哪一步 <a class="header-anchor" href="#页表隔离改的是哪一步" aria-label="Permalink to &quot;页表隔离改的是哪一步&quot;">​</a></h2><p>旧的共享地址空间设计可以在用户态页表中留下内核页的 supervisor-only 映射。它让硬件知道物理位置，再依靠访问权限拒绝普通读取。Linux x86 的页表隔离（PTI）让用户态使用一套只保留少量内核入口所需区域的页表，进入内核时切到完整的内核页表。对已经移出用户态页表的内核页，前面的例题就从“存在，但权限拒绝”变成了“当前地址空间中没有这个映射”。改善发生在地址翻译这一环。</p><details class="details custom-block"><summary>练习：两个错误报告相同吗</summary><p>仍用第一条指令，比较两个情形。甲中目标页存在，但用户读权限不足。乙中目标页在当前页表里不存在。异常如何区分？能否在乙的题设中沿用甲的物理地址？</p><p>两者都触发页错误，但错误码的第 0 位分别为 1 和 0。乙没有提供这条翻译，不能拿甲的物理地址继续推演。要分析硬件是否还会对这类情形产生别的影响，需要针对另一种机制查证。Intel 在说明中将这里讨论的经典权限型情形与 L1TF 区分开来。</p></details><details class="details custom-block"><summary>练习：一次页错误和未命中能说明什么</summary><p>同一测量区间里出现页错误，L1 未命中计数也升高。能否据此判断故障加载的值被依赖指令使用了？</p><p>页错误支持的是架构上的访问被拒绝。L1 未命中计数汇总了这个区间内符合计数条件的事件，普通访问和<a href="./microarch-02-prefetch.html#prefetch-feedback">预取活动</a>也能改变计数。要证明这个值被内部使用，还需要把故障指令与具体的后继操作联系起来。若要判断能否形成侧信道，还要说明观测者能区分什么，可回看<a href="./microarch-04b-observation.html">时间差与证据</a>。</p></details><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li><a href="https://meltdownattack.com/meltdown.pdf" target="_blank" rel="noreferrer">Meltdown 原论文</a></li><li><a href="https://www.intel.com/content/www/us/en/developer/articles/technical/intel-sdm.html" target="_blank" rel="noreferrer">Intel SDM 第 3A 卷 Paging 的访问权与页错误小节</a></li><li><a href="https://www.intel.com/content/www/us/en/developer/articles/technical/software-security-guidance/technical-documentation/analysis-speculative-execution-side-channels.html#variant-3-rogue-data-cache-load" target="_blank" rel="noreferrer">Intel 对 Rogue Data Cache Load 的说明</a></li><li><a href="https://docs.kernel.org/arch/x86/pti.html" target="_blank" rel="noreferrer">Linux x86 页表隔离说明</a></li></ul><nav class="article-nav" aria-label="系列文章导航"><p><a href="./microarch-04d-spectre-v1.html" class="article-nav-card article-nav-prev" rel="prev"><span class="article-nav-text"><small>上一篇</small><strong>Spectre v1 中的边界检查为何会被越过</strong></span></a></p><p><a href="./microarch-04c-variants.html" class="article-nav-card article-nav-next" rel="next"><span class="article-nav-text"><small>下一篇</small><strong>Spectre 变体中的分支与访存推测</strong></span></a></p></nav>`,28)]))}const b=a(p,[["render",r]]);export{h as __pageData,b as default};
